// src/pages/AdminDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { CSSTransition, TransitionGroup } from "react-transition-group";
import "./AdminDashboard.css"; // We'll add CSS for smooth transitions

const Card = ({ title, children }) => (
  <div
    className="card"
  >
    <h2 className="card-title">{title}</h2>
    {children}
  </div>
);

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [message, setMessage] = useState("");
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [selectedElectionVotingOpen, setSelectedElectionVotingOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("VotingStatus");

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API Calls ----------------
  const fetchVotingState = async () => { try { const res = await api.get("/admin/voting-state"); setVotingOpen(res.data.votingOpen); } catch (err) { handleApiError(err); } };
  const fetchPendingUsers = async () => { try { const res = await api.get("/admin/pending-users"); setPendingUsers(res.data); } catch (err) { handleApiError(err); } };
  const fetchCandidates = async () => { try { const res = await api.get("/admin/candidates"); setCandidates(res.data); } catch (err) { handleApiError(err); } };
  const fetchLogs = async () => { try { const res = await api.get("/admin/logs"); setLogs(res.data); } catch (err) { handleApiError(err); } };
  const fetchElections = async () => {
    try {
      const res = await api.get("/admin/elections");
      const sorted = res.data.sort((a, b) => new Date(b.startsAt) - new Date(a.startsAt));
      setElections(sorted);
      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);
        setSelectedElectionVotingOpen(firstElection.votingOpen);
        fetchResults(firstElection.id);
      }
    } catch (err) { handleApiError(err); }
  };
  const fetchResults = async (electionId) => { try { const res = await api.get("/admin/results", { params: { electionId } }); setResults(res.data.positionResults || {}); setWinners(res.data.winners || {}); } catch (err) { handleApiError(err); } };

  const toggleVoting = async () => { try { const res = await api.post("/admin/toggle-voting"); setVotingOpen(res.data.votingOpen); setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`); } catch (err) { handleApiError(err); } };
  const approveUser = async (id) => { try { await api.post(`/admin/approve-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const rejectUser = async (id) => { try { await api.post(`/admin/reject-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const approveCandidate = async (id) => { try { await api.post(`/admin/approve-candidate/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const deleteCandidate = async (id) => { if (!window.confirm("Delete this candidate?")) return; try { await api.delete(`/admin/candidates/${id}`); fetchCandidates(); } catch (err) { handleApiError(err); } };
  const generateReport = async () => { try { const res = await api.post("/admin/generate-report"); setReportHash(res.data.hash); } catch (err) { handleApiError(err); } };
  const handleElectionChange = (id) => { const election = elections.find((el) => el.id === id); setSelectedElection(id); setSelectedElectionVotingOpen(election?.votingOpen ?? false); fetchResults(id); };

  useEffect(() => {
    if (!token) { navigate("/login"); return; }
    const init = async () => { await fetchVotingState(); await fetchPendingUsers(); await fetchCandidates(); await fetchLogs(); await fetchElections(); };
    init();
  }, [token]);

  // ---------------- Rendered Sections ----------------
  const renderContent = () => {
    switch (activeTab) {
      case "VotingStatus":
        return (
          <Card title="Voting Status">
            <p style={{ fontWeight: "bold", color: votingOpen ? "green" : "red" }}>{votingOpen ? "Open" : "Closed"}</p>
            <button onClick={toggleVoting} style={{ marginTop: "10px", padding: "10px 20px", borderRadius: "8px", border: "none", backgroundColor: votingOpen ? "#dc3545" : "#28a745", color: "#fff", cursor: "pointer", fontWeight: "bold" }}>{votingOpen ? "Close Voting" : "Open Voting"}</button>
          </Card>
        );
      case "PendingUsers":
        return (
          <Card title="Pending Voter Registrations">
            {pendingUsers.length === 0 ? <p style={{ color: "#777", fontStyle: "italic" }}>No pending users.</p> :
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr style={{ background: "#f1f1f1" }}><th style={{ padding: "8px", textAlign: "left" }}>Student #</th><th style={{ padding: "8px", textAlign: "left" }}>Name</th><th style={{ padding: "8px", textAlign: "left" }}>Email</th><th style={{ padding: "8px", textAlign: "center" }}>Actions</th></tr></thead>
                <tbody>{pendingUsers.map(u => <tr key={u.id} style={{ borderTop: "1px solid #eee" }}><td style={{ padding: "8px" }}>{u.studentNumber}</td><td style={{ padding: "8px" }}>{u.name}</td><td style={{ padding: "8px" }}>{u.email}</td><td style={{ padding: "8px", textAlign: "center" }}><button onClick={() => approveUser(u.id)} style={{ marginRight: "5px", background: "#28a745", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Approve</button><button onClick={() => rejectUser(u.id)} style={{ background: "#dc3545", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Reject</button></td></tr>)}</tbody>
              </table>}
          </Card>
        );
      case "Candidates":
        return (
          <Card title="Candidates">
            {/* Candidates table */}
            {/* Keep same as previous code for candidates */}
          </Card>
        );
      case "Results":
        return (
          <Card title="Election Results">
            {/* Election dropdown + results table */}
            {/* Keep same as previous code for results */}
          </Card>
        );
      case "Reports":
        return (
          <Card title="Reports">
            <button onClick={generateReport} style={{ padding: "10px 18px", borderRadius:"8px", border:"none", backgroundColor:"#007bff", color:"#fff", cursor:"pointer", fontWeight:"bold" }}>Generate Final Report</button>
            {reportHash && <p style={{ marginTop:"10px", fontSize:"0.9rem", color:"#555" }}>Cryptographic Hash: <span style={{ fontFamily:"monospace" }}>{reportHash}</span></p>}
          </Card>
        );
      default: return null;
    }
  };

  return (
    <div className="dashboard-container">
      {/* Sidebar */}
      <aside className={`sidebar ${sidebarOpen ? "open" : "collapsed"}`}>
        <button className="hamburger" onClick={() => setSidebarOpen(!sidebarOpen)}>☰</button>
        <nav className="sidebar-nav">
          <span className={activeTab==="VotingStatus"?"active":""} onClick={()=>setActiveTab("VotingStatus")}>🏠 Voting Status</span>
          <span className={activeTab==="PendingUsers"?"active":""} onClick={()=>setActiveTab("PendingUsers")}>🧑 Pending Users</span>
          <span className={activeTab==="Candidates"?"active":""} onClick={()=>setActiveTab("Candidates")}>👤 Candidates</span>
          <span className={activeTab==="Results"?"active":""} onClick={()=>setActiveTab("Results")}>📊 Results</span>
          <span className={activeTab==="Reports"?"active":""} onClick={()=>setActiveTab("Reports")}>📄 Reports</span>
        </nav>
        <button className="sidebar-logout" onClick={() => {logout(); navigate("/login")}}>Logout</button>
      </aside>

      {/* Main Content */}
      <main className="main-content">
        <TransitionGroup>
          <CSSTransition key={activeTab} timeout={300} classNames="fade">
            {renderContent()}
          </CSSTransition>
        </TransitionGroup>
        {message && <p className="global-message">{message}</p>}
      </main>
    </div>
  );
}
